/// Echoing Slash. Cost 1, Attack, AllEnemies. Deal 10 (13 upgraded) damage
/// to every alive enemy as a POWERED attack. C# `EchoingSlash.cs` declares
/// `new DamageVar(10m, ValueProp.Move)` and deals it via `CreatureCmd.Damage(
/// HittableEnemies, Damage, base.Owner.Creature, this)` — a normal `Move`
/// attack, so dealer Strength (additive) and Weak plus target-side
/// Vulnerable (multiplicative) all apply. The earlier port followed the
/// Python pin (`sts2-rl-agent@01c094d:sts2_env/cards/silent.py:673-679`,
/// `ValueProp.NONE`), one of the known Python-vs-C# divergences — the C#
/// decomp is authoritative, so this routes through
/// [`deal_damage_to_all_alive_enemies`] with [`ValueProps::MOVE`] (fixes the
/// Silent quick/mid-tier ECHOING_SLASH `monsters[*].hp` divergences).
///
/// Bead `sts2-rs-5tetc`: wires the cascading-on-kill rider that C#
/// `EchoingSlash.cs` OnPlay implements as
/// `while (attackCount > 0) { attackCount--; attackCount += kills; }`.
/// Each AoE pass adds one extra pass per enemy killed by it; the loop
/// terminates when a pass yields no new kills. Prior port only did one
/// AoE pass.
pub(crate) fn play_echoing_slash(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    let base = current_card_damage(state);
    let mut attack_count: i32 = 1;
    while attack_count > 0 {
        attack_count -= 1;
        // C# counts `DamageResult.WasTargetKilled` for THIS wave's hits
        // (`attackCount += enumerable.Count(r => r.WasTargetKilled)`), so the
        // rewave count is the number of *targeted* enemies that died — NOT the
        // net change in the alive-enemy count. Snapshot the wave's targets up
        // front and tally how many of THEM are dead afterward. A net-delta
        // (`alive_before - alive_after`) underflows to 0 when a kill SPAWNS
        // more enemies — e.g. killing a PHROG_PARASITE triggers
        // `InfestedPower.AfterDeath` (spawns 4 Wrigglers), so alive goes 1 -> 4
        // and the prior `saturating_sub` reported 0 kills, skipping the rewave
        // that C# lands on the freshly-spawned Wrigglers (Silent fuzz seed 19:
        // monsters[*].hp uniformly +10 in Rust). Bead `sts2-rs-5tetc` follow-up.
        let targets: smallvec::SmallVec<[sts2_core::CreatureUid; 8]> = state
            .enemy_uids
            .iter()
            .copied()
            .filter(|uid| {
                state
                    .creatures
                    .iter()
                    .any(|c| c.id == uid.0 && c.current_hp > 0)
            })
            .collect();
        let _ = deal_damage_to_all_alive_enemies(
            state,
            base,
            ValueProps::MOVE,
            Some(CardId::EchoingSlash),
        );
        // A targeted enemy counts as killed when it is now absent from
        // `creatures` (removed on death) or present at <= 0 HP.
        let kills = targets
            .iter()
            .filter(|uid| {
                !state
                    .creatures
                    .iter()
                    .any(|c| c.id == uid.0 && c.current_hp > 0)
            })
            .count();
        attack_count = attack_count.saturating_add(i32::try_from(kills).unwrap_or(i32::MAX));
    }
    EffectResult::Resolved
}

